import{_ as n,c as i,o as r,a3 as t}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"Datenschutzerklärung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/privacy.md","filePath":"de/guide/privacy.md","lastUpdated":1787284674000}'),a={name:"de/guide/privacy.md"};function l(s,e,o,h,u,d){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="datenschutzerklarung" tabindex="-1">Datenschutzerklärung <a class="header-anchor" href="#datenschutzerklarung" aria-label="Permalink to &quot;Datenschutzerklärung&quot;">​</a></h1><p>ClipboxAI ist ein intelligenter Zwischenablagen-Manager für macOS. Ihre Privatsphäre hat für uns Priorität.</p><h2 id="local-first-design" tabindex="-1">Local-First-Design <a class="header-anchor" href="#local-first-design" aria-label="Permalink to &quot;Local-First-Design&quot;">​</a></h2><ul><li>Ihr Zwischenablagen-Verlauf wird vollständig auf Ihrem Mac gespeichert.</li><li>Eingebaute lokale Aktionen (extract links, count stats, collapse blank lines und On-Device-ML-Vorschläge) laufen vollständig offline.</li><li>Für die Nutzung der Kern-App ist kein Konto oder Registrierung erforderlich.</li><li>Für die lokale Zwischenablagen-Verwaltung und On-Device-Funktionen ist keine Internetverbindung erforderlich.</li></ul><h2 id="cloud-ki-optional" tabindex="-1">Cloud-KI (Optional) <a class="header-anchor" href="#cloud-ki-optional" aria-label="Permalink to &quot;Cloud-KI (Optional)&quot;">​</a></h2><p>ClipboxAI kann optional Cloud-KI-Anbieter (wie DeepSeek, MiniMax, GLM, Kimi, Mistral oder einen lokalen Ollama-Server) nutzen, um erweiterte Aktionen wie Zusammenfassen, Übersetzen und benutzerdefinierte Prompts auszuführen.</p><ul><li>Wenn aktiviert, wird der ausgewählte Text oder Zwischenablage-Inhalt <strong>direkt an den von Ihnen konfigurierten Anbieter</strong> gesendet, unter Verwendung <strong>Ihres eigenen API-Schlüssels</strong>.</li><li>Ihr API-Schlüssel wird ausschließlich im Keychain Ihres Macs gespeichert und niemals zu uns hochgeladen.</li><li>Sie können Cloud-KI jederzeit deaktivieren und weiterhin lokale Funktionen nutzen.</li><li>Der Zwischenablagen-Verlauf wird <strong>nicht</strong> automatisch in die Cloud gesendet; Cloud-Anfragen werden nur ausgelöst, wenn Sie eine Cloud-Aktion ausführen.</li></ul><h2 id="was-wir-nicht-erfassen" tabindex="-1">Was wir nicht erfassen <a class="header-anchor" href="#was-wir-nicht-erfassen" aria-label="Permalink to &quot;Was wir nicht erfassen&quot;">​</a></h2><ul><li>Wir erfassen Ihre Zwischenablage-Inhalte, Dokumente oder Dateien nicht.</li><li>Wir verfolgen Ihre Aktivität, Ihr Surfverhalten oder Nutzungsmuster nicht.</li><li>Wir betreiben keinen Server, der Ihre Zwischenablage-Daten empfängt.</li><li>Wir binden keine Analysesoftware, Werbe- oder Tracking-SDKs von Drittanbietern ein.</li><li>Wir haben kein Telemetrie-System.</li></ul><h2 id="welche-daten-lokal-gespeichert-werden" tabindex="-1">Welche Daten lokal gespeichert werden <a class="header-anchor" href="#welche-daten-lokal-gespeichert-werden" aria-label="Permalink to &quot;Welche Daten lokal gespeichert werden&quot;">​</a></h2><p>Die folgenden Daten werden ausschließlich auf Ihrem Gerät gespeichert:</p><ul><li><strong>Zwischenablagen-Verlauf</strong>: Aktuelle Einträge für den Schnellzugriff (auf Ihrem Mac).</li><li><strong>App-Einstellungen</strong>: Theme, Sprachpräferenz, aktivierte Aktionen, Anbieter-Konfiguration.</li><li><strong>API-Schlüssel</strong>: Sicher im lokalen Keychain gespeichert (nur wenn Sie einen Cloud-Anbieter konfigurieren).</li><li><strong>Benutzerdefinierte Aktionen</strong>: Prompts und Konfiguration, die Sie erstellen.</li><li><strong>Protokolle</strong>: Debug-Protokolle zur Fehlerbehebung (können jederzeit gelöscht werden).</li></ul><h2 id="von-der-app-verwendete-berechtigungen" tabindex="-1">Von der App verwendete Berechtigungen <a class="header-anchor" href="#von-der-app-verwendete-berechtigungen" aria-label="Permalink to &quot;Von der App verwendete Berechtigungen&quot;">​</a></h2><ul><li><strong>Accessibility / Full Disk Access</strong>: Erforderlich, um die System-Zwischenablage zu lesen und globale Tastenkürzel bereitzustellen.</li><li><strong>Benachrichtigungen</strong>: Optional, für Abschluss-Hinweise bei länger laufenden Cloud-Anfragen.</li></ul><p>Sie können diese Berechtigungen jederzeit in <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit</strong> verwalten.</p><h2 id="in-app-kaufe-lizenz" tabindex="-1">In-App-Käufe / Lizenz <a class="header-anchor" href="#in-app-kaufe-lizenz" aria-label="Permalink to &quot;In-App-Käufe / Lizenz&quot;">​</a></h2><p>Lizenzkäufe (falls vorhanden) werden von Apple über den Mac App Store abgewickelt. ClipboxAI empfängt oder speichert Ihre Zahlungsdaten nicht. Lizenz-Belege werden lokal gespeichert, um den Besitz zu verifizieren.</p><h2 id="drittanbieter-dienste" tabindex="-1">Drittanbieter-Dienste <a class="header-anchor" href="#drittanbieter-dienste" aria-label="Permalink to &quot;Drittanbieter-Dienste&quot;">​</a></h2><p>ClipboxAI selbst enthält keine Analysen, Werbung oder Tracking-Dienste von Drittanbietern. Wenn Sie einen Cloud-KI-Anbieter aktivieren, werden Ihre Anfragen von diesem Anbieter gemäß dessen eigener Datenschutzerklärung bearbeitet.</p><h2 id="datenschutz-anfragen" tabindex="-1">Datenschutz-Anfragen <a class="header-anchor" href="#datenschutz-anfragen" aria-label="Permalink to &quot;Datenschutz-Anfragen&quot;">​</a></h2><p>Da ClipboxAI alle Daten lokal auf Ihrem Gerät speichert, halten wir keine personenbezogenen Daten auf unseren Servern vor. Wenn Sie Fragen zum Datenschutz haben, kontaktieren Sie uns bitte.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Für Datenschutz-Fragen öffnen Sie ein Issue unter <a href="https://github.com/clipboxAI/clipboard-site/issues" target="_blank" rel="noreferrer">GitHub Issues</a> oder schreiben Sie uns an <a href="mailto:clipboxai@w3cub.com" target="_blank" rel="noreferrer">clipboxai@w3cub.com</a>.</p>',23)])])}const p=n(a,[["render",l]]);export{g as __pageData,p as default};
